		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;

#pragma scop
#pragma omp parallel for private(i, j) schedule(static)
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE t = SCALAR_VAL(0.0);
      DATA_TYPE yy = SCALAR_VAL(0.0);
#pragma omp simd reduction(+:t,yy)
